@functools.total_ordering
class TempFileContextManager:
 def __init__(self, prefix):
 self.prefix = prefix
 self.temp_file = None

 def __enter__(self):
 self.temp_file = self._create_tempfile()
 return self.temp_file

 def __exit__(self, exc_type, exc_val, exc_tb):
 if self.temp_file is not None:
 self.temp_file.close()
 self.temp_file = None

 def _create_tempfile(self):
 try:
 self.temp_file = open(f"{self.prefix}_{os.getpid()}.tmp", "w+b")
 return self.temp_file
 except OSError as e:
 if e.errno != errno.EEXIST:
 raise
 self._create_tempfile()

@contextlib.contextmanager
def tempfile(prefix=""):
 return TempFileContextManager(prefix)

